const n6 = node({ type: "n8n-nodes-base.code", version: 2, config: {"name":"Extrair Dados Chatwoot","parameters":{"jsCode":"\nconst body = $('Filtrar Evento').first().json;\nconst sender = body.sender || {};\nconst conv = body.conversation || {};\nconst ci = conv.contact_inbox || {};\nlet numero = sender.phone_number || ci.source_id || '';\nnumero = String(numero).replace(/^\\+/, '').replace(/\\D/g, '');\nconst nome = sender.name || 'Parceiro';\nconst mensagem = (body.content || '').trim();\nconst conversationId = conv.id;\nconst accountId = (body.account && body.account.id) || 1;\nconst inboxId = (body.inbox && body.inbox.id) || 4;\nconst assigneeId = conv.assignee_id != null ? conv.assignee_id : null;\nconst status = conv.status || 'open';\nconst messageId = body.id;\n// Allowlist de parceiros desativada: cadastro/configuracao de parceiro ainda nao implementado.\n// Para reativar, restaurar a lista PARCEIROS e voltar a compor 'autorizado' em deveResponder.\nconst autorizado = true;\nconst deveResponder = assigneeId === null || assigneeId === undefined || assigneeId === '' || assigneeId === 0;\nreturn [{ json: { autorizado, deveResponder, numero, nome, mensagem, conversationId, accountId, inboxId, assigneeId, status, messageId, chave: 'session:' + numero, chaveTriagem: 'triagem:' + numero } }];\n"},"position":[1104,800]}, output: [{}] });
