const n14 = node({ type: "n8n-nodes-base.code", version: 2, config: {"name":"Motor Triagem","parameters":{"jsCode":"\nconst dados = $('Extrair Dados Chatwoot').first().json;\nconst guard = $('Avaliar Estado Atendimento').first().json;\nconst estadoRaw = $('Buscar Estado Triagem').first().json.estadoRaw;\nconst nome = dados.nome || 'Parceiro';\nconst msgOrig = (dados.mensagem || '').trim();\nconst m = msgOrig.toLowerCase().trim();\nconst now = new Date().toISOString();\nlet _resumo = '';\ntry { _resumo = ((($('Webhook Chatwoot Triagem').first().json.body.conversation.meta.sender.custom_attributes) || {}).resumo_atendimentos) || ''; } catch (e9) { _resumo = ''; }\n\n// Historico do contato: conversas anteriores (abertura, fechamento, desfecho e resumo de cada uma), via Chatwoot.\nlet _hist = '';\nlet _temHist = false;\ntry {\n  const _hr = $('Buscar Historico Contato').first().json || {};\n  const _lista = Array.isArray(_hr.payload) ? _hr.payload : [];\n  const _atual = String($('Extrair Dados Chatwoot').first().json.conversationId);\n  const _dt = function (s) { if (!s) return ''; const x = new Date(Number(s) * 1000 - 3 * 3600000); return ('0' + x.getUTCDate()).slice(-2) + '/' + ('0' + (x.getUTCMonth() + 1)).slice(-2) + '/' + x.getUTCFullYear(); };\n  const _ant = _lista.filter(function (c) { return c && String(c.id) !== _atual; })\n    .sort(function (a, b) { return Number(b.created_at || 0) - Number(a.created_at || 0); })\n    .slice(0, 5);\n  _temHist = _ant.length > 0;\n  _hist = _ant.map(function (c) {\n    const ca = c.custom_attributes || {};\n    const fim = ca.sdr_outcome_at ? _dt(ca.sdr_outcome_at) : (c.status === 'resolved' ? _dt(c.last_activity_at || c.timestamp) : '');\n    const desf = ca.sdr_outcome === 'won' ? 'ganho' : (ca.sdr_outcome === 'lost' ? 'perdido' : (c.status === 'resolved' ? 'resolvida' : 'em aberto'));\n    const res = String(ca.sdr_resumo || '').replace(/\\s+/g, ' ').trim();\n    return '- Conversa #' + c.id + ': aberta em ' + _dt(c.created_at) + (fim ? ', fechada em ' + fim : '') + ' (' + desf + '). Resumo: ' + (res || 'sem resumo');\n  }).join('\\n');\n} catch (eh) { _hist = ''; _temHist = false; }\nconst _voltou = (_resumo || _temHist) ? 'Que bom te ver de novo! ' : '';\n\nconst PRODUTO_TEAM = { consorcio: 'consórcio', fin_imob: 'crédito pj', home_equity: 'crédito pj', vida: 'seguro de vida', saude: 'saude', corporate: 'corporate e elementares', outro: 'atendimento parceiros' };\nconst TEAM_DEFAULT = 'atendimento parceiros';\n\nconst MENU_TIPO = 'Oi! Eu sou a Bia, sua assistente aqui na Finture. Vou te direcionar rápido pro time certo. Me conta o que você precisa:\\n\\n1) Criar uma indicação\\n2) Dúvida operacional\\n3) Comissionamento\\n4) Outro\\n\\nResponde só com o número.';\nconst MENU_PRODUTO = 'Beleza! Sobre qual produto é?\\n\\n1) Consórcio\\n2) Financiamento Imobiliário\\n3) Home Equity\\n4) Seguro de Vida\\n5) Saúde\\n6) Corporate e Elementares\\n7) Outro\\n\\nResponde com o número.';\nconst PEDIR_DESCRICAO = 'Fechou! Me manda em uma ou duas linhas o que você precisa, que eu já passo pro time certo.';\n\nlet estado = null;\nif (estadoRaw) { try { estado = JSON.parse(estadoRaw); } catch (e) { estado = null; } }\nif (estado && estado.updatedAt) {\n  const idade = Date.now() - Date.parse(estado.updatedAt);\n  if (isNaN(idade) || idade > 3600000) estado = null;\n}\n\nfunction soNumero(s) { const t = String(s).replace(/[^0-9]/g, ''); return t.length ? t : null; }\nfunction ehSaudacao(x) { return /^(oi+|ola|ol[aá]|opa|e a[ií]|hey|hi|bom dia|boa tarde|boa noite|tudo bem|tudo bom|blz|beleza|menu|voltar|in[ií]cio)[!.?\\s]*$/i.test(x); }\nfunction pedeAtendente(x) { return /(atendente|humano|falar com (uma )?pessoa|me conecta|quero falar com|chama algu[eé]m|transfer[ei]|pessoa de verdade)/i.test(x); }\nfunction parseTipo(x) {\n  const n = soNumero(x);\n  if (n === '1') return 'indicacao';\n  if (n === '2') return 'operacional';\n  if (n === '3') return 'comissionamento';\n  if (n === '4') return 'outro';\n  if (/indica/i.test(x)) return 'indicacao';\n  if (/opera/i.test(x)) return 'operacional';\n  if (/comiss/i.test(x)) return 'comissionamento';\n  if (/^outr/i.test(x)) return 'outro';\n  return null;\n}\nfunction parseProduto(x) {\n  const n = soNumero(x);\n  if (n === '1') return 'consorcio';\n  if (n === '2') return 'fin_imob';\n  if (n === '3') return 'home_equity';\n  if (n === '4') return 'vida';\n  if (n === '5') return 'saude';\n  if (n === '6') return 'corporate';\n  if (n === '7') return 'outro';\n  if (/cons[oó]rcio/i.test(x)) return 'consorcio';\n  if (/financ|imobil|im[oó]vel/i.test(x)) return 'fin_imob';\n  if (/home ?equity|equity/i.test(x)) return 'home_equity';\n  if (/vida/i.test(x)) return 'vida';\n  if (/sa[uú]de/i.test(x)) return 'saude';\n  if (/corporate|elementar|empresarial|frota|patrimonial/i.test(x)) return 'corporate';\n  if (/^outr/i.test(x)) return 'outro';\n  return null;\n}\n\nconst base = {\n  accountId: dados.accountId,\n  conversationId: dados.conversationId,\n  numero: dados.numero,\n  nome: nome,\n  chave: dados.chave,\n  chaveTriagem: dados.chaveTriagem,\n  mensagem: msgOrig,\n  labelsAtuais: guard.labelsAtuais || [],\n  customAttrsAtuais: guard.customAttrsAtuais || {}\n};\n\nfunction outPerguntar(mensagemBot, etapa, tipoDemanda, produto) {\n  const novoEstado = { etapa: etapa, tipoDemanda: tipoDemanda || null, produto: produto || null, descricao: null, updatedAt: now };\n  return [{ json: Object.assign({}, base, { acao: 'perguntar', mensagemBot: mensagemBot, novoEstadoJson: JSON.stringify(novoEstado) }) }];\n}\nfunction outHandoff(teamName, tipoDemanda, produto, descricao, motivo) {\n  return [{ json: Object.assign({}, base, { acao: 'handoff', teamName: teamName || TEAM_DEFAULT, tipoDemanda: tipoDemanda || null, produto: produto || null, descricao: descricao || '', motivo: motivo || 'Triagem', confirmacao: '' }) }];\n}\nfunction outInterpretar(etapaAtual, tipoDemandaAtual, produtoAtual) {\n  return [{ json: Object.assign({}, base, { acao: 'interpretar', etapaAtual: etapaAtual, tipoDemandaAtual: tipoDemandaAtual || null, produtoAtual: produtoAtual || null }) }];\n}\n\nif (pedeAtendente(m)) {\n  const prod = estado && estado.produto ? estado.produto : null;\n  const tipo = estado && estado.tipoDemanda ? estado.tipoDemanda : null;\n  const desc = (estado && estado.descricao) ? estado.descricao : msgOrig;\n  return outHandoff(prod ? PRODUTO_TEAM[prod] : TEAM_DEFAULT, tipo, prod, desc, 'Parceiro pediu atendimento humano');\n}\n\n// Retomada: humano devolveu a conversa à IA (botão \"Devolver à IA\"). Sem estado de\n// triagem no Redis, NÃO reapresenta o menu: segue pelo Haiku com o motivo e as\n// pendências anotadas pelo atendente.\nconst _ret = guard.retomada || null;\nif (!estado && _ret) {\n  const _tri = _ret.triage || {};\n  return [{ json: Object.assign({}, base, { acao: 'interpretar', etapaAtual: 'retomada', tipoDemandaAtual: _tri.tipo || null, produtoAtual: _tri.produto || null, retomada: _ret }) }];\n}\n\nif (!estado) {\n  if (!msgOrig || ehSaudacao(m) || m.length < 3) {\n    return outPerguntar(_voltou + MENU_TIPO, 'tipo', null, null);\n  }\n  return outInterpretar('inicio', null, null);\n}\n\nif (estado.etapa === 'tipo') {\n  const t = parseTipo(m);\n  if (t) return outPerguntar(MENU_PRODUTO, 'produto', t, null);\n  return outInterpretar('tipo', null, null);\n}\nif (estado.etapa === 'produto') {\n  const p = parseProduto(m);\n  if (p) return outPerguntar(PEDIR_DESCRICAO, 'descricao', estado.tipoDemanda, p);\n  return outInterpretar('produto', estado.tipoDemanda || null, null);\n}\nif (estado.etapa === 'descricao') {\n  return outHandoff(estado.produto ? PRODUTO_TEAM[estado.produto] : TEAM_DEFAULT, estado.tipoDemanda || null, estado.produto || null, msgOrig, 'Triagem concluída');\n}\nreturn outPerguntar(MENU_TIPO, 'tipo', null, null);\n"},"position":[2432,800]}, output: [{}] });
