const n29 = node({ type: "n8n-nodes-base.code", version: 2, config: {"name":"Extrair Team ID","parameters":{"jsCode":"\nconst items = $input.all();\nlet teams = [];\nif (items.length === 1 && Array.isArray(items[0].json)) teams = items[0].json;\nelse if (items.length === 1 && items[0].json && Array.isArray(items[0].json.payload)) teams = items[0].json.payload;\nelse teams = items.map(function(i){ return i.json; });\nconst prep = $('Preparar Handoff').first().json;\nfunction norm(s){ return String(s || '').trim().toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g, ''); }\nconst TEAM_NAME = String(prep.teamName || 'atendimento parceiros');\nlet team = null;\nfor (let i = 0; i < teams.length; i++) {\n  const t = teams[i];\n  if (t && norm(t.name) === norm(TEAM_NAME)) { team = t; break; }\n}\nconst teamId = team ? team.id : null;\nconst teamEncontrado = teamId !== null && teamId !== undefined && teamId !== '';\nreturn [{ json: { teamId, teamEncontrado, teamName: TEAM_NAME, accountId: prep.accountId, conversationId: prep.conversationId } }];\n"},"position":[4432,800]}, output: [{}] });
